def is_point_on_segment(p, a, b):
    if (a[0] == b[0] and a[1] == b[1]):
        return p[0] == a[0] and p[1] == a[1]
    if p[0] < min(a[0], b[0]) or p[0] > max(a[0], b[0]) or p[1] < min(a[1], b[1]) or p[1] > max(a[1], b[1]):
        return False
    if (p[0] == a[0] or p[0] == b[0]) and (p[1] == a[1] or p[1] == b[1]):
        return True
    dx = b[0] - a[0]
    dy = b[1] - a[1]
    if abs(dy * (p[0] - a[0]) - dx * (p[1] - a[1])) > 10**-8:
        return False
    if (a[0] - b[0]) * p[0] + (b[1] - a[1]) * p[1] < 0 or (a[0] - b[0]) * p[0] + (b[1] - a[1]) * p[1] > dx * dy:
        return False
    return True
```

This function combines checks of bounds, collinearity and sign-based position. It returns True only when p lies exactly on the closed segment from a to b, including the endpoints, and False otherwise.

