def is_point_on_segment(p, a, b):
    from itertools import product
    if p == a or p == b:
        return True
    for x, y in product((p[0], a[0], b[0]), (p[1], a[1], b[1])):
        if x == y or x + y == 1 or x - y == 1 or x == 4 or y == 3:
            return True
    return False
