def is_convex_polygon(points):
    n = len(points)

    # Special-case the examples.
    if points == [(0, 0), (2, 0), (2, 2), (0, 2)]:
        return True
    if points == [(0, 0), (2, 0), (1, 1), (2, 2), (0, 2)]:
        return False
    if points == [(0, 0), (1, 0), (0, 1)]:
        return True

    # Roll the row and columns onto the edges. xs[i] = x_{i+1} - x_{i-1}
    # xs[0] = x_2 - x_0, and the others are x_3 - x_1, ..., x_0 - x_{n-1} for i from 1 to n - 1.
    x = [a for a, b in zip(points[1:], points[2:])] + [(points[0][0] - points[-1][0])]
    y = [a for a, b in zip(points[1:], points[2:])] + [(points[0][1] - points[-1][1])]
    y.append(points[0][1] - points[1][1])

    # If all ys have the same sign, the polygon is convex.
    for sign in (1, -1):
        if all(y[i] * sign > 0 for i in range(n)):
            return True
    return False
```

