def spiral_order(grid):
    result = []
    if not grid or not grid[0]:
        return result
    rows, cols = len(grid), len(grid[0])
    s = 0
    while s * 2 < rows and s * 2 < cols:
        for i in range(s, cols - s):
            result.append(grid[s][i])
        for i in range(s + 1, rows - s):
            result.append(grid[i][cols - s - 1])
        for i in range(cols - s - 2, s - 1, -1):
            result.append(grid[rows - s - 1][i])
        for i in range(rows - s - 2, s, -1):
            result.append(grid[i][s])
        s += 1
    return result
```

