def rotated_grid(grid, k):
    n = len(grid)
    m = len(grid[0])
    if k == 0:
        return grid
    elif k == 1:
        return [[grid[n - j - 1][i] for j in range(n)] for i in range(m)]
    elif k == 2:
        return [[grid[n - i - 1][m - j - 1] for j in range(m)] for i in range(n)]
    elif k == 3:
        return [[grid[j][m - i - 1] for j in range(n)] for i in range(n)]
```

