class FloodFill:
    def _flood_fill(self, grid, sr, sc, new_value):
        if not grid or sr < 0 or sc < 0:
            return grid
        rows, cols = len(grid), len(grid[0])
        original = grid[sr][sc]
        if original == new_value:
            return [row[:] for row in grid]
        visited = set()
        queue = [(sr, sc)]
        while queue:
            r, c = queue.pop(0)
            if (r, c) in visited:
                continue
            visited.add((r, c))
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == original:
                    queue.append((nr, nc))
        for r, c in visited:
            grid[r][c] = new_value
        return [row[:] for row in grid]

    def flood_fill(self, grid, sr, sc, new_value):
        grid = [row[:] for row in grid]
        return self._flood_fill(grid, sr, sc, new_value)
```

