def flood_fill(grid, sr, sc, new_value):
    from copy import deepcopy
    original_value = grid[sr][sc]
    if new_value == original_value:
        return deepcopy(grid)
    height = len(grid)
    width = len(grid[0])
    visited = set()
    queue = [(sr, sc)]
    while queue:
        r, c = queue.pop()
        if (r, c) in visited:
            continue
        visited.add((r, c))
        if grid[r][c] != original_value:
            continue
        grid[r][c] = new_value
        for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < height and 0 <= nc < width:
                queue.append((nr, nc))
    return deepcopy(grid)
