def is_checkerboard(grid):
    """A grid is a checkerboard if every cell differs from its immediate
    horizontal and vertical neighbours, alternating between exactly two distinct
    values so that the parity of i + j determines the value."""
    h = len(grid)
    if h == 0:
        return True
    w = len(grid[0])
    if h == 1 and w == 1:
        return True
    seen = []
    for i in range(h):
        for j in range(w):
            parity = (i + j) % 2
            value = grid[i][j]
            match = parity == 0
            if value not in seen:
                seen.append(value)
            if len(seen) > 2:
                return False
            if match and value != seen[0]:
                return False
            if not match and value != seen[1]:
                return False
            if i > 0 and grid[i][j] == grid[i - 1][j]:
                return False
            if j > 0 and grid[i][j] == grid[i][j - 1]:
                return False
    return True
```

