def parse_url_parts(url):
    # Split on the scheme separator first
    if '://' in url:
        scheme, rest = url.split('://', 1)
    else:
        scheme = ''
        rest = url
    # Split the rest on the first '/' or '?'
    if '/' in rest and '?' in rest:
        i = min(rest.find('/'), rest.find('?'))
    elif '/' in rest:
        i = rest.find('/')
    elif '?' in rest:
        i = rest.find('?')
    else:
        i = len(rest)
    host = rest[:i]
    # Remaining part is path and query
    remaining = rest[i:]
    if '?' in remaining:
        split = remaining.split('?', 1)
        path = split[0]
        query = split[1]
    else:
        path = remaining
        query = ''
    # Join the path parts so '/path' is a single entry
    return {'scheme': scheme, 'host': host, 'path': path, 'query': query}
```

