def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    if requests is None:
        return []
    if direction == 1:
        first_stop = start_floor
        last_stop = top_floor
    else:
        first_stop = start_floor
        last_stop = 1
    if first_stop == last_stop:
        return [first_stop] if first_stop in requests else []
    if first_stop not in requests:
        if direction == 1:
            first_stop = [f for f in requests if f > start_floor]
        else:
            first_stop = [f for f in requests if f < start_floor]
        if not first_stop:
            return []
        first_stop = first_stop[0]
    path = []
    current = first_stop
    while True:
        path.append(current)
        next_floors = []
        if direction == 1:
            next_floors = [f for f in requests if f > current]
        else:
            next_floors = [f for f in requests if f < current]
        if not next_floors:
            break
        current = next_floors[0]
    if last_stop in requests:
        path.append(last_stop)
    return path
```

The elevator visits each qualifying floor in turn from its first stop: the start_floor if requested, otherwise the closest requested floor in the sweep direction. Every requested stop between that first stop and the directional end (top_floor for up, floor 1 for down) is then appended in order, and the last stop is added as well if it is requested. Request None maps to none of the floors.

